// --------------------------------------------

void mc_testbench::ccs_input_stream_chan_checker(ac_channel<ac_int<512, false > > &input_stream, unsigned int chan_size)
{
   if (!input_stream_pointer_set) {
      input_stream_pointer = &(input_stream);
      input_stream_pointer_set = true;
   } else if (input_stream_pointer != &(input_stream) && remaining_ccs_input_stream == 0) {
      std::ostringstream msg; msg.str("");
      msg << "Interface input_stream source switched to a different object in testbench with "
          << remaining_ccs_input_stream << " values remaining in input fifo. No data mismatch detected." <<" @ " << sc_time_stamp();
      SC_REPORT_INFO("User testbench", msg.str().c_str());
      input_stream_pointer = &(input_stream);
   } else if (input_stream_pointer != &(input_stream) && remaining_ccs_input_stream > 0 && remaining_ccs_input_stream != chan_size) {
      std::ostringstream msg; msg.str("");
      msg << "Interface input_stream source switched to a different object in testbench with "
          << remaining_ccs_input_stream << " values remaining in input fifo. Simulation mismatch likely. Check golden vs DUT comparison values for errors." <<" @ " << sc_time_stamp();
      SC_REPORT_WARNING("User testbench", msg.str().c_str());
      ccs_chan_ptr_mismatch = true;
   }
}
