// ============================================
// Function: capture_IN
// --------------------------------------------

void mc_testbench::capture_IN(ac_channel<ac_int<512, false> > &input_stream, ac_channel<ac_int<64, false> > &weight_stream, ac_channel<ac_int<512, false> > &p3_stream, ac_channel<ac_int<512, false> > &p4_stream, ac_channel<ac_int<512, false> > &p5_stream)
{
   that->wait_on_input_required();
   // Input capture functions
   that->capture_input_stream(input_stream);
   that->capture_weight_stream(weight_stream);
   that->wait_on_empty_inputs();
   // Output channel watermarks
   that->remaining_p3_stream_golden = that->ccs_p3_stream_debug_size(p3_stream);
   that->remaining_p4_stream_golden = that->ccs_p4_stream_debug_size(p4_stream);
   that->remaining_p5_stream_golden = that->ccs_p5_stream_debug_size(p5_stream);
}
// ============================================
// Function: capture_OUT
// --------------------------------------------

void mc_testbench::capture_OUT(ac_channel<ac_int<512, false> > &input_stream, ac_channel<ac_int<64, false> > &weight_stream, ac_channel<ac_int<512, false> > &p3_stream, ac_channel<ac_int<512, false> > &p4_stream, ac_channel<ac_int<512, false> > &p5_stream)
{
   // Output capture functions
   that->capture_p3_stream(p3_stream);
   that->capture_p4_stream(p4_stream);
   that->capture_p5_stream(p5_stream);
   // Input channel watermarks
   static bool ccs_input_stream_msg_once = true;
   that->remaining_ccs_input_stream = that->ccs_input_stream_debug_size(input_stream);
   if ((testbench::enable_idle_sync_mode || ccs_input_stream_msg_once) && that->remaining_ccs_input_stream != 0) {
      cout << "Warning: Testbench input channel 'input_stream' not empty. Remaining size: " << that->remaining_ccs_input_stream << endl;
      if (ccs_input_stream_msg_once) {
         cout << "All elements have been captured and passed to the RTL DUT, please do not remove data or delete/replace the channel." << endl;
         ccs_input_stream_msg_once = false;
      }
   }
   static bool ccs_weight_stream_msg_once = true;
   that->remaining_ccs_weight_stream = that->ccs_weight_stream_debug_size(weight_stream);
   if ((testbench::enable_idle_sync_mode || ccs_weight_stream_msg_once) && that->remaining_ccs_weight_stream != 0) {
      cout << "Warning: Testbench input channel 'weight_stream' not empty. Remaining size: " << that->remaining_ccs_weight_stream << endl;
      if (ccs_weight_stream_msg_once) {
         cout << "All elements have been captured and passed to the RTL DUT, please do not remove data or delete/replace the channel." << endl;
         ccs_weight_stream_msg_once = false;
      }
   }
   testbench::clear_transaction_controls();
   static bool default_idle_sync_mode = ac_env::read_bool("SCVerify_IDLE_SYNCHRONIZATION_MODE",false);
   testbench::enable_idle_sync_mode = default_idle_sync_mode;
}
// ============================================
// Function: wait_on_input_required
// --------------------------------------------

void mc_testbench::wait_on_input_required()
{
   wait(SC_ZERO_TIME); //give fifos a chance to update
   static sc_time previous_timestamp = SC_ZERO_TIME;
   sc_time current_timestamp = sc_time_stamp();
   sc_time timestamp_delta = current_timestamp - previous_timestamp;
   if (!wait_on_input_timeouts && current_timestamp > previous_timestamp && previous_timestamp > SC_ZERO_TIME) {
      wait_on_input_average = (wait_on_input_average + timestamp_delta) / 2;
   }
   bool timed_out = false;
   sc_time timeout = wait_on_input_average * testbench::wait_on_input_timeout_factor;
   previous_timestamp = current_timestamp;
   while (atleast_one_active_input) {
      if (( !d_disable_on_empty || _captured_input_stream) && ccs_input_stream->used() == 0) return;
      if (( !d_disable_on_empty || _captured_weight_stream) && ccs_weight_stream->used() == 0) return;
      if (!(_captured_input_stream || _captured_weight_stream)) return;
      cpp_testbench_active.write(false);
      if (wait_on_input_average > SC_ZERO_TIME && current_timestamp > timestamp_delta) {
         wait(timeout, ccs_input_stream->ok_to_put() | ccs_weight_stream->ok_to_put());
         if (sc_time_stamp() >= (current_timestamp + timeout))
            timed_out = true;
      } else
         wait(ccs_input_stream->ok_to_put() | ccs_weight_stream->ok_to_put());
      cpp_testbench_active.write(true);
      if (timed_out) {
         if (!wait_on_input_timeouts) {
            std::ostringstream msg;
            msg << "wait_on_input_required() transactor fifo read event time out: no reads for " << timeout << ", re-enabling the testbench and disabling this message.";
            SC_REPORT_WARNING(name(), msg.str().c_str());
         }
         ++wait_on_input_timeouts;
         return;
      }
   }
}
// ============================================
// Function: wait_on_empty_inputs
// --------------------------------------------

void mc_testbench::wait_on_empty_inputs()
{
   if (!(_captured_input_stream || _captured_weight_stream)) {
      if (testbench::wait_on_empty_inputs > 0.0) {
         wait(SC_ZERO_TIME);
         cpp_testbench_active.write(false);
         wait(testbench::wait_on_empty_inputs, SC_NS);
      }
   }
}
// ============================================
// Function: exec_run
// --------------------------------------------

void mc_testbench::exec_run(ac_channel<ac_int<512, false> > &input_stream, ac_channel<ac_int<64, false> > &weight_stream, ac_channel<ac_int<512, false> > &p3_stream, ac_channel<ac_int<512, false> > &p4_stream, ac_channel<ac_int<512, false> > &p5_stream)
{
   #ifndef CCS_SCVERIFY_USE_CCS_BLOCK
   wait_for_idle_sync();
   capture_IN(input_stream, weight_stream, p3_stream, p4_stream, p5_stream);
   GPTBackbonePhase3::run(input_stream, weight_stream, p3_stream, p4_stream, p5_stream);
   capture_OUT(input_stream, weight_stream, p3_stream, p4_stream, p5_stream);
   #endif
}
// ============================================
// Function: start_of_simulation
// --------------------------------------------

void mc_testbench::start_of_simulation()
{
   set_enable_stalls(false);
   if (ac_env::read_int("SCVerify_AUTOWAIT", 0) != 0) { //explicitly 0 means off
      SC_REPORT_INFO(name(), "SCVerify AUTOWAIT is enabled for this simulation.");
   }
}
// ============================================
// Function: end_of_simulation
// --------------------------------------------

void mc_testbench::end_of_simulation()
{
   if (!_checked_results) {
      SC_REPORT_INFO(name(), "Testbench exited early or ran into deadlock");
      check_results();
   }
}
// ============================================
// Function: check_results
// --------------------------------------------

void mc_testbench::check_results()
{
   if (_checked_results) return;
   _checked_results = true;
   cout<<endl;
   cout<<"Checking results"<<endl;
   if (main_exit_code) _failed = true;
   int _num_outputs_checked = 0;
   bool _has_capture_counts = false;
   std::ostringstream mctb_msg;
   
   if (!_capture_p3_stream) {
      cout<<"'p3_stream' - warning, output was optimized away"<<endl;
   } else {
      _num_outputs_checked++;
      _failed |= p3_stream_comp->check_results(p3_stream_capture_count,testbench::p3_stream_skip_noerr);
      _has_capture_counts |= !!(p3_stream_capture_count);
   }
   if (!_capture_p4_stream) {
      cout<<"'p4_stream' - warning, output was optimized away"<<endl;
   } else {
      _num_outputs_checked++;
      _failed |= p4_stream_comp->check_results(p4_stream_capture_count,testbench::p4_stream_skip_noerr);
      _has_capture_counts |= !!(p4_stream_capture_count);
   }
   if (!_capture_p5_stream) {
      cout<<"'p5_stream' - warning, output was optimized away"<<endl;
   } else {
      _num_outputs_checked++;
      _failed |= p5_stream_comp->check_results(p5_stream_capture_count,testbench::p5_stream_skip_noerr);
      _has_capture_counts |= !!(p5_stream_capture_count);
   }
   cout<<endl;
   if (_num_outputs_checked == 0) {
      cout<<"Error: All outputs were optimized away. No output values were compared."<<endl;
      _failed = _failed || (_num_outputs_checked == 0);
   }
   if (!_has_capture_counts) {
      cout<<"Error: Nothing to compare, all output capture counts are zero."<<endl;
      _failed = true;
   }
   if (main_exit_code) cout << "Error: C++ Testbench 'main()' returned a non-zero exit code ("<<main_exit_code<<"). Check your testbench." <<endl;
   mctb_msg.clear();
   if (_failed) mctb_msg << "Simulation FAILED";
   else         mctb_msg << "Simulation PASSED";
   mctb_msg << " @ " << sc_time_stamp();
   if (ccs_chan_ptr_mismatch && _failed)
      mctb_msg << endl << "An input channel was switched before the input fifo was fully empty. Check your testbench.";
   SC_REPORT_INFO(this->name(), mctb_msg.str().c_str());
   if (manual_flush_enabled) {
      cout << "Warning: Re-enabled empty inputs with last known value at the end of simulation to manually flush DUT outputs from the pipeline." << endl
           << " If simulation was still active then consider increasing the wait count with the control testbench::manual_flush_wait_cycles. Currently: " << testbench::manual_flush_wait_cycles << endl
           << " Manual flushing may be prevented by enabling loop pipeline flushing with the directive PIPELINE_STALL_MODE." << endl;
   }
   
   if (!!wait_on_input_timeouts) {
      cout << "Warning: wait_on_input_required() read event time outs: '" << wait_on_input_timeouts << "'. Multiple time outs may slow simulation throughput." << endl
           << " Long IO stalls from testbench wait_ctrls or AUTOWAIT can slow read transactions and trigger this timeout." << endl
           << " However, this can also occur when the testbench is not supplying enough data to the RTL DUT." << endl
           << " Use the SCVerify control testbench::wait_on_input_timeout_factor to change the time out duration. Currently: " << testbench::wait_on_input_timeout_factor << ", using an averaged input wait time of: " << wait_on_input_average << endl;
   }
   if (_failed && d_warn_nb_empty_input_capture) {
      cout << "Warning: When no inputs are captured for a given call to the DUT the mc_testbench::wait_on_input_required() function will return to prevent deadlock." << endl
           << " This will advance the testbench until there is at least one active input, which may result in non-blocking channels being read early by the RTL." << endl
           << " Consider manually throttling the DUT calls by using the testbench wait control testbench::wait_on_empty_inputs (SC_NS)." << endl;
   }
}
// ============================================
// Function: failed
// --------------------------------------------

bool mc_testbench::failed()
{
   return _failed;
}
// ============================================
// Function: set_failed
// --------------------------------------------

void mc_testbench::set_failed(bool fail)
{
   _failed = fail;
}
// ---------------------------------------------------------------
// Process: SC_METHOD wait_for_end

void mc_testbench::wait_for_end() {
   #ifdef VCS_SYSTEMC
   if (hdl_elaboration_only()) return;
   #endif
   // If run() has not finished, we do nothing here
   if (!testbench_ended) return;
   // check for completed outputs
   if (p3_stream_comp->get_compare_count() < p3_stream_capture_count) {end_of_sim_wait_event.notify(1,SC_NS); return;}
   if (p4_stream_comp->get_compare_count() < p4_stream_capture_count) {end_of_sim_wait_event.notify(1,SC_NS); return;}
   if (p5_stream_comp->get_compare_count() < p5_stream_capture_count) {end_of_sim_wait_event.notify(1,SC_NS); return;}
   // If we made it here, all outputs have flushed. Check the results
   testbench_aw_event.notify(SC_ZERO_TIME);
   SC_REPORT_INFO(name(), "Simulation completed");
   check_results();
   sc_stop();
}
// ---------------------------------------------------------------
// Process: SC_METHOD manual_flush_output_monitor

void mc_testbench::manual_flush_output_monitor() {
   #ifdef VCS_SYSTEMC
   if (hdl_elaboration_only()) return;
   #endif
   if (!testbench_ended) return;
   //Monitor the waiting outputs and send an event to scverify_top::manual_flush().
   //Adjust timing with the control testbench::manual_flush_wait_cycles.
   manual_flush_output_active = false;
   static int p3_stream_comp_compare_count = 0;
   if ( p3_stream_comp_compare_count < p3_stream_comp->get_compare_count() ) {
      p3_stream_comp_compare_count = p3_stream_comp->get_compare_count();
      manual_flush_output_active = true;
   }
   static int p4_stream_comp_compare_count = 0;
   if ( p4_stream_comp_compare_count < p4_stream_comp->get_compare_count() ) {
      p4_stream_comp_compare_count = p4_stream_comp->get_compare_count();
      manual_flush_output_active = true;
   }
   static int p5_stream_comp_compare_count = 0;
   if ( p5_stream_comp_compare_count < p5_stream_comp->get_compare_count() ) {
      p5_stream_comp_compare_count = p5_stream_comp->get_compare_count();
      manual_flush_output_active = true;
   }
   if (0
      || p3_stream_comp_compare_count < p3_stream_capture_count
      || p4_stream_comp_compare_count < p4_stream_capture_count
      || p5_stream_comp_compare_count < p5_stream_capture_count
   ) {
      manual_flush_event.notify(SC_ZERO_TIME);
   }
}
// ---------------------------------------------------------------
// Process: SC_THREAD run

void mc_testbench::run() {
   testbench::enable_idle_sync_mode = false;
   testbench::idle_sync_stable_cycles = 1;
   testbench::wait_on_input_timeout_factor = 10;
   testbench::wait_on_empty_inputs = 0.0;
   testbench::manual_flush_wait_cycles = 15000;
   ccs_chan_ptr_mismatch = false;
   testbench::enable_rom_sync = false;
   testbench::_dummy_assign = false;
   testbench::input_stream_ignore = false;
   testbench::input_stream_skip = false;
   testbench::input_stream_skip_quiet = false;
   testbench::input_stream_skip_once = false;
   testbench::input_stream_skip_noerr = false;
   testbench::input_stream_array_comp_first = -1;
   testbench::input_stream_array_comp_last = -1;
   testbench::input_stream_wait_ctrl.clear();
   input_stream_capture_count = 0;
   input_stream_iteration_count = 0;
   input_stream_pointer_set = false;
   testbench::weight_stream_ignore = false;
   testbench::weight_stream_skip = false;
   testbench::weight_stream_skip_quiet = false;
   testbench::weight_stream_skip_once = false;
   testbench::weight_stream_skip_noerr = false;
   testbench::weight_stream_array_comp_first = -1;
   testbench::weight_stream_array_comp_last = -1;
   testbench::weight_stream_wait_ctrl.clear();
   weight_stream_capture_count = 0;
   weight_stream_iteration_count = 0;
   weight_stream_pointer_set = false;
   testbench::p3_stream_ignore = false;
   testbench::p3_stream_skip = false;
   testbench::p3_stream_skip_quiet = false;
   testbench::p3_stream_skip_once = false;
   testbench::p3_stream_skip_noerr = false;
   testbench::p3_stream_array_comp_first = -1;
   testbench::p3_stream_array_comp_last = -1;
   testbench::p3_stream_use_mask = false;
   testbench::p3_stream_output_mask = (ac_int<512, false >) ~0;
   testbench::p3_stream_wait_ctrl.clear();
   p3_stream_capture_count = 0;
   p3_stream_iteration_count = 0;
   testbench::p4_stream_ignore = false;
   testbench::p4_stream_skip = false;
   testbench::p4_stream_skip_quiet = false;
   testbench::p4_stream_skip_once = false;
   testbench::p4_stream_skip_noerr = false;
   testbench::p4_stream_array_comp_first = -1;
   testbench::p4_stream_array_comp_last = -1;
   testbench::p4_stream_use_mask = false;
   testbench::p4_stream_output_mask = (ac_int<512, false >) ~0;
   testbench::p4_stream_wait_ctrl.clear();
   p4_stream_capture_count = 0;
   p4_stream_iteration_count = 0;
   testbench::p5_stream_ignore = false;
   testbench::p5_stream_skip = false;
   testbench::p5_stream_skip_quiet = false;
   testbench::p5_stream_skip_once = false;
   testbench::p5_stream_skip_noerr = false;
   testbench::p5_stream_array_comp_first = -1;
   testbench::p5_stream_array_comp_last = -1;
   testbench::p5_stream_use_mask = false;
   testbench::p5_stream_output_mask = (ac_int<512, false >) ~0;
   testbench::p5_stream_wait_ctrl.clear();
   p5_stream_capture_count = 0;
   p5_stream_iteration_count = 0;
   testbench testbench_inst(sc_argc(), sc_argv());
   main_exit_code = testbench_inst.main();
   cout<<"Info: Execution of user-supplied C++ testbench 'main()' has completed @ " << sc_time_stamp() << " with exit code = " << main_exit_code << endl;
   cout<<endl;
   cout<<"Info: Collecting data completed"<<endl;
   cout<<"   captured "<<input_stream_capture_count<<" values of input_stream"<<endl;
   cout<<"   captured "<<weight_stream_capture_count<<" values of weight_stream"<<endl;
   cout<<"   captured "<<p3_stream_capture_count<<" values of p3_stream"<<endl;
   cout<<"   captured "<<p4_stream_capture_count<<" values of p4_stream"<<endl;
   cout<<"   captured "<<p5_stream_capture_count<<" values of p5_stream"<<endl;
   testbench_ended = true;
   testbench_end_event.notify(SC_ZERO_TIME);
}
